import fs from "fs";
import path from "path";
import matter from "gray-matter";

export type Post = {
  slug: string;
  title: string;
  date: string;
  summary?: string;
  tags?: string[];
  content: string;
};

function getDir(type: "lab" | "article") {
  return path.join(process.cwd(), "content", type);
}

export function getPosts(type: "lab" | "article"): Post[] {
  const dir = getDir(type);
  if (!fs.existsSync(dir)) return [];

  const files = fs
    .readdirSync(dir)
    .filter((f) => f.toLowerCase().endsWith(".mdx") || f.toLowerCase().endsWith(".md"));

  return files.map((file) => {
    const slug = file.replace(/\.(mdx|md)$/i, "");
    const raw = fs.readFileSync(path.join(dir, file), "utf8");
    const { data, content } = matter(raw);

    return {
      slug,
      title: data.title || slug,
      date: data.date || "",
      summary: data.summary || "",
      tags: data.tags || [],
      content,
    };
  });
}

export function getPost(type: "lab" | "article", slug: string): Post | null {
  const dir = getDir(type);

  const exts = ["mdx", "MDX", "md", "MD"];
  for (const ext of exts) {
    const file = path.join(dir, `${slug}.${ext}`);
    if (fs.existsSync(file)) {
      const raw = fs.readFileSync(file, "utf8");
      const { data, content } = matter(raw);

      return {
        slug,
        title: data.title || slug,
        date: data.date || "",
        summary: data.summary || "",
        tags: data.tags || [],
        content,
      };
    }
  }

  return null;
}