import { getPost } from "@/lib/posts";
import { notFound } from "next/navigation";

export default function LabPost({ params }: { params: { slug: string } }) {
  const post = getPost("article", params.slug);

  if (!post) notFound();

  return (
    <main className="p-10 text-white max-w-3xl mx-auto">
      <h1 className="text-3xl mb-2">{post.title}</h1>
      <div className="opacity-60 mb-6">{post.date}</div>

      <article className="prose prose-invert">
        <pre style={{ whiteSpace: "pre-wrap" }}>{post.content}</pre>
      </article>
    </main>
  );
}